def countComponents(n: int, edges: list[list[int]]) -> int:
    parent = list(range(n))
    def find(i):
        while parent[i] != i:
            i = parent[i]
        return i
    components = n
    for u, v in edges:
        root_u = find(u)
        root_v = find(v)
        if root_u != root_v:
            parent[root_u] = root_v
            components -= 1
    return components

